#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<int> bit;

    Fenwick(int n) : n(n), bit(n + 1, 0) {}

    void add(int idx, int val) {
        for (; idx <= n; idx += idx & -idx) bit[idx] += val;
    }

    int sum(int idx) {
        int res = 0;
        for (; idx > 0; idx -= idx & -idx) res += bit[idx];
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long X1, X2;
    cin >> N >> X1 >> X2;

    vector<long long> v1(N), v2(N);

    for (int i = 0; i < N; i++) {
        long long A, B;
        cin >> A >> B;
        v1[i] = A * X1 + B;
        v2[i] = A * X2 + B;
    }

    vector<long long> comp = v2;
    sort(comp.begin(), comp.end());
    comp.erase(unique(comp.begin(), comp.end()), comp.end());

    vector<pair<long long, long long>> lines(N);
    for (int i = 0; i < N; i++) {
        lines[i] = {v1[i], v2[i]};
    }

    sort(lines.begin(), lines.end(), [](const auto& a, const auto& b) {
        return a.first < b.first;
    });

    Fenwick fw((int)comp.size());
    long long concordant = 0;

    int i = 0;
    while (i < N) {
        int j = i;
        while (j < N && lines[j].first == lines[i].first) j++;

        for (int k = i; k < j; k++) {
            int idx = lower_bound(comp.begin(), comp.end(), lines[k].second) - comp.begin() + 1;
            concordant += fw.sum(idx - 1);
        }

        for (int k = i; k < j; k++) {
            int idx = lower_bound(comp.begin(), comp.end(), lines[k].second) - comp.begin() + 1;
            fw.add(idx, 1);
        }

        i = j;
    }

    long long total = 1LL * N * (N - 1) / 2;
    cout << total - concordant << '\n';

    return 0;
}
